from report_content import SECTIONS, section

PROXY_ROWS = [
('プロキシ設定','EngineFamily','必須。固定の省略値なし','MYSQL','Aurora MySQLを選択。8.4.7はターゲットDBのエンジン版でありProxyに8.4.7と入力する項目ではない。','S05 S13'),
('プロキシ設定','DBProxyName','必須。自動共通値なし','app-prod-tokyo / app-prod-osaka','同じ命名規約で地域と用途を識別。識別子と接続用FQDNを区別。','S13'),
('プロキシ設定','IdleClientTimeout','1800秒','1800秒を基準','SQLの実行上限ではなく、クライアントが何も要求しない接続の期限。JBoss側idleを300秒にして先に返却する。','S05 S07'),
('ターゲットグループ','TargetGroupName','defaultを自動生成','default','追加ターゲットグループは作成できない。「追加のターゲットグループの設定」は既存defaultの詳細設定として整理する。','S12'),
('ターゲットグループ','DBClusterIdentifiers','未登録。コンソール選択時に登録','同じ地域のAuroraクラスターID','1 Proxyに1 Aurora cluster。Writer/ReaderのDNS文字列やGlobal writer endpointは入力しない。','S05 S08'),
('ターゲットグループ','MaxConnectionsPercent','MySQLは100%','80%を初期案','管理直結等へ余裕を残す設計。DB実効max_connectionsと実測MaxDatabaseConnectionsAllowedを使用。80%自体が性能を保証するわけではない。','S06 S07'),
('追加のTG設定','MaxIdleConnectionsPercent','MySQLはMaxConnectionsPercentの50%','40%を明示','80%枠の50%＝DB max_connectionsの40%。現在開いている接続の40%という意味ではない。急増と費用/メモリを検証して調整。','S06 S07'),
('追加のTG設定','ConnectionBorrowTimeout','120秒、範囲0～300秒','3秒','同一Proxyをオンラインとバッチで共有するため短い側へ合わせる。SQL実行時間の上限ではない。バッチの混雑待ちはジョブ側で再計画する。','S06 S07'),
('追加のTG設定','SessionPinningFilters','指定なし','空配列を維持','EXCLUDE_VARIABLE_SETSは無条件に使わない。セッション状態を別利用者に流す正しさのリスクを作ってまで多重化率を上げない。','S05 S09'),
('追加のTG設定','InitQuery','なし','原則空。共通値はDBパラメータで管理','必要時だけ全利用者共通のSETを使用。アプリ利用者別のSQLや秘密を入れない。online/batchの異なる時間制限はInitQuery一つでは分離できない。','S05 S06'),
('認証','DefaultAuthScheme','NONE','NONE','IAM DB認証を使用しないという本件の前提。NONEは無認証を意味せず、Secrets ManagerのDB資格情報を使う。','S05 S13'),
('認証','Auth[].AuthScheme','有効な指定はSECRETS','SECRETS','Proxy→DB間のパスワードをSecrets Managerから取得。Parameter Storeのホスト情報だけでは代用できない。','S14'),
('認証','Auth[].SecretArn','NONE方式では指定必須','同じ地域のonline/batch用秘密を登録','通常ユーザーとバッチユーザーを別にし、必要権限だけ付与。全権限のmasterをアプリに使用しない。','S05'),
('認証','Auth[].ClientPasswordAuthType','APIのMySQL既定はMYSQL_CACHING_SHA2_PASSWORD','MYSQL_CACHING_SHA2_PASSWORDを明示','DBユーザーもcaching_sha2_password、クライアントも対応ドライバとTLS。古い画面のnative選択例を流用しない。','S14 S22'),
('認証','Auth[].IAMAuth','APIで統一省略値は明示されない','DISABLEDを明示','コンソールではNot Allowed相当。DB認証をIAMにしないことと、AWS APIのIAM権限を使わないことは別。','S05 S14'),
('認証','RoleArn','Secrets参照等のロールが必要','Proxy専用ロール','rds.amazonaws.comの引受け、対象秘密のGetSecretValue、必要時のみ対象KMS鍵のDecryptを許可。AWSアカウント全秘密への権限を付けない。','S05 S13'),
('接続','RequireTLS','API資料は省略時の固定値を明示しない','trueを必須指定','暗号化を既定の画面チェック状態へ依存させない。DB側require_secure_transport=ONとクライアントVERIFY_IDENTITYも併用。','S05 S13 S30'),
('接続','VPC','DBと同一VPCが必要','地域内のDBと同一VPC','Proxyはpublic endpointを持たない。アプリの別VPCアクセスは追加Proxyエンドポイント等を明示して設計。','S08'),
('接続','VpcSubnetIds','2つ以上の適切なサブネットが必要','2 AZ以上のprivate subnet','IP余裕を確保。現行既定endpointは選ばれた2 AZへ配置される。3 subnetを指定しても既定endpointが3 AZ配置とは限らない。','S05 S08'),
('接続','VpcSecurityGroupIds','作成経路やVPCに依存','Proxy専用SGを明示','デフォルトSGに依存しない。app/batch/許可された管理ホストから3306、DB SGへ3306を許可。','S05'),
('追加の接続設定','EndpointNetworkType','IPV4','IPV4を基準','IPv6採用要件がある場合に限りDUAL/IPV6を選び、DNS、SG、サブネット、経路を同時設計する。','S13'),
('追加の接続設定','TargetConnectionNetworkType','IPV4','IPV4を基準','現在のターゲット側選択はIPV4/IPV6。DUALはターゲット側の値ではない。IPv6はDBのdual-stack対応が必要。','S13'),
('追加の接続設定','既定エンドポイントの役割','READ_WRITE','オンラインと更新バッチの共通入口','SQLのSELECTもWriterへ向かう。書込主体の昇格が済んでいるかをreadinessで確認する。','S04 S11'),
('追加の接続設定','追加ROエンドポイント','作成されない','読取専用処理があるときだけ作成','Readerへ向ける別DNS。追加料金・SG・独立接続設定が必要。ReaderがないときのWriterフォールバックを前提にしない。','S11 S52'),
('追加の接続設定','追加RWエンドポイント','作成されない','別VPC等の要件がなければ不要','追加endpointでターゲットグループを増やせるわけではない。online/batch別の借用期限が必須なら別Proxyを評価する。','S11 S12'),
('接続','待受ポート','MySQL Proxyは3306','3306','Proxy→DBはターゲットに設定されたポートを使う。今回はDBも3306に統一してSGを明確化する。','S08'),
('詳細設定','DebugLogging','API上の省略時値は未明示。通常設計は無効','falseを明示','調査時のみ期限付きで有効化。現行作成資料では24時間後に自動無効化。SQL・個人情報・コストへの影響を管理する。','S05 S13'),
('詳細設定','Tags','任意、固定値なし','System/Environment/Region/Owner/CostCenter/DRRole','障害時の識別とコスト集計用。タグにパスワード、個人名等の秘密を入れない。','S13'),
('サービス制約','クライアント接続最大寿命','24時間、変更不可','24時間未満で計画的に更新','EAPへ存在しないmaxLifetime属性を追加しない。idle排出、validate-on-match、12時間以内の計画的なコンテナ更新等で対処し、利用中切断にも備える。','S07'),
('サービス制約','Proxyが保持するidle DB接続','通常5分でidle判定','サービス管理のまま','MaxIdleConnectionsPercentは保持枠を調整する。DB wait_timeoutを短くしてProxyの裏側接続を無闇に切らない。','S07'),
('変更反映','DBパラメータ変更のProxy反映','DBではdynamicでもProxy側再起動要件あり','DB再起動・プール再接続を変更手順へ含める','公式Proxy制約ではインスタンス再起動が必要。クラスタレベルは全体を対象にする。東京大阪の順次変更・復帰確認を手順化する。','S08'),
]

SECTIONS.append(dict(sheet='07_Proxy設定', title='RDS Proxyの全設計区分：既定値と明示設定',
 intro='コンソールの見出しは更新され得るためAPI名を併記する。省略時の既定が公式APIに明示されない項目は断定せず、推奨構成では明示的に設定する。',
 headers=['設計区分','設定/API名','デフォルト・制約','本構成の推奨初期値','理由・相互作用・確認事項','根拠'], rows=PROXY_ROWS))

section('08_接続経路の厳格評価','TCP3306とSecurity Groupだけでは接続設計の合格条件にならない',
        '記載された構成の実設定は未取得。以下は設計記述への評価であり、実際のSGが過剰開放されていると断定するものではない。', [
('総合評価','要改善・条件付き採用','「VPC内部通信でSGにより3306制御」だけでは、誰が、どの経路で、何の権限で、どの証明書を検証して接続するかが不明。暗号化と操作追跡も保証されない。','経路表、送信元SG、接続対象、IAM、DBユーザー、TLS、監査、承認済み保守作業を揃えて判断する。','S08 S10 設計提案'),
('アプリの経路','app-sg → proxy-sg:3306のみ','本件の通常接続はProxyで統一。app-sgからdb-sgへの3306を常時許可すると、アプリがProxyを迂回でき、接続数制御の前提が崩れる。','proxy-sg inbound: app-sg/batch-sg。db-sg inbound: proxy-sg。送信元0.0.0.0/0、全社CIDR、VPC全体CIDRの一括許可を避ける。','設計提案'),
('バッチの経路','batch-sg → proxy-sg:3306','バッチが東京に残り大阪Writerへ書く構成は「環境ごと大阪へ切替」の例外になる。長い通信経路、東京障害、重複起動を再評価する必要がある。','バッチ実行基盤とジョブスケジューラも大阪に切替可能にする。共有ファイルや外部データ入口も地域依存を除く。','設計提案'),
('運用端末','恒常的なDB直結は推奨しない','インターネット上の端末は、そのままではVPC内部に存在しない。VPN/Direct Connect/踏み台/SSM管理ホスト等の経路を示す必要がある。','通常参照は個人別読取権限と許可された管理経路。MFA、端末管理、短時間セッション、接続元の記録を設ける。','S08 設計提案'),
('Writer/Readerへの管理直結','期限付きの例外として残す','Proxy異常調査や特定セッション観測ではDBインスタンスへ直接接続する経路が必要な場合がある。常用経路と同じSGにまとめない。','admin-breakglass-sgからdb-sg:3306を保守時間だけ許可。変更記録と期限を自動管理。Writer/ReaderのDNS名だけでは個別SG制御できない。','設計提案'),
('SGの限界','DNS名・SQL種別・本人を制御しない','SGはIP/ポート/プロトコル等で通信を許可する仕組み。DBエンドポイント文字列ごとのSQL許可や、同じポートのSELECT/DELETEの区別はできない。','同一クラスター内のWriter/Readerは役割が変わる。読取専用性はDB権限で守り、DNS名がreaderだから安全という運用をしない。','設計提案'),
('TLS','クライアントとDBの両区間で有効','private IPでも誤接続や盗聴のリスクがゼロになるわけではない。暗号化だけで相手の身元を確認しない設定は不十分。','RequireTLS=true、require_secure_transport=ON、Connector/J sslMode=VERIFY_IDENTITY、TLSv1.2/TLSv1.3。IP直書きと独自CNAMEを避ける。','S08 S10 S30'),
('証明書','Proxy用とAurora直結用を区別','ProxyはACM/Amazon Trust Services系の証明書、Aurora直結はRDS CA。片方のCAだけを詰めた独自truststoreでは他方の接続が失敗し得る。','JDKの信頼ストアを確認しProxyの実FQDNでTLS検証。保守用直結はRDS CA更新手順も持つ。verify=false等で回避しない。','S10 S30'),
('SSMトンネル','localhost名による証明書不一致に注意','SSMポート転送はVPC内へ到達させるが、クライアントURLをlocalhostにするとホスト名検証と証明書が一致しない。','検証対象ホスト名を保持できるツール/トンネル設定を検証。難しい場合は管理ホスト内で実FQDNに接続。ポート転送はSQL内容の監査を代替しない。','S30 設計提案'),
('NACL・ルート・DNS','SGだけで疎通を断定しない','往路3306に加えNACLの戻り通信、ルート、DNS解決、サブネットのIP容量が必要。SGはstateful、NACLはstatelessという性質を区別する。','公式Proxyのcross-AZ NACL要件に従い必要範囲を設定。TCP疎通、TLS、認証、SQLまで段階別に試験する。','S05'),
('監査','ネットワークとSQLのログを分ける','VPC Flow Logsは許可/拒否や通信量、CloudTrailはAWS API操作、DB監査ログはDBユーザーの操作を記録する。どれか一つですべては分からない。','online/batch/個人管理者のDBアカウントを分離。監査ログには必要なイベントだけを出し、SQL中の機密値、保存期間、アクセス権を管理する。','S20 設計提案'),
('極めて厳しい合格条件','東京遮断状態でも大阪で起動・認証・更新','設定上privateでもDNSやSecretsが東京に依存していれば不合格。ネットワークの成功はDBトランザクションの成功と別。','アプリ直結拒否、管理例外期限切れ、非TLS拒否、誤CA/誤FQDN拒否、大阪書込、接続数制限、SQL監査を証跡付きで確認する。','設計提案'),
])

section('09_パラメータ設計原則','パラメータグループの継承、Serverless固有動作、用途別の設定責任',
        '全件表は後半4シート。直接接続オンライン・直接接続バッチは比較用。採用構成では共用Proxy列を使う。', [
('設定の階層','クラスター → インスタンス → セッション','クラスターパラメータ群は全体の既定を持つ。一部はインスタンス群で上書きでき、さらにSESSION対応値は接続ごとに変更できる。単なるファイルの設定順ではない。','同一DBへonline/batchが接続する場合、ユーザー別に別インスタンス群を自動選択する機能はない。DB共通値と接続/SQLごとの値に分離する。','S17 S21'),
('設定値の表記','APIの型・許容値に変換して投入','本文のON/OFFは有効/無効の意味。API許容値が0,1なら1/0を使用する。秒・ms等の単位表記は説明であり、数値パラメータへ単位文字列を含めない。','既定/推奨一覧は設計資料。適用前にAllowedValues、IsModifiable、MinimumEngineVersion、ApplyTypeを確認して変更要求を作成する。','S56 S57'),
('全件と変更可能の区別','表示される全行を残して適用条件を付記','クラスタ専用131、共通/インスタンス299を合わせて430。IsModifiable=falseも一覧にはある。これを「すべて変更できる」とは説明しない。','取得API、リージョン、時刻、MinimumEngineVersion、ApplyTypeを保存。8.4.8専用の1行は対象外として推奨設定を出さない。','S56 S57'),
('デフォルト式','式を実数へ勝手に置き換えない','DBInstanceClassMemory、AllocatedStorage、ServerId等はAWSが解決する式や置換値。ACU×2GiBをそのまま入れた暗算が実効値と一致するとは限らない。','実機の@@GLOBAL.max_connections等を記録する。APIにParameterValueがないものはengine-defaultと表示しCommunityの参考値と分離する。','S17 S20'),
('自動調整の4項目','固定値上書きは採用しない','innodb_buffer_pool_size、innodb_purge_threads、table_definition_cache、table_open_cacheはServerless v2が容量に合わせて調整し、カスタム値を使わない。','全件表ではAPI上変更可でも「v2自動調整」と表示する。プロビジョンド向けの固定メモリ最適化をそのまま適用しない。','S17'),
('max_connections','最大ACUで決まり、変更後の再起動を考慮','スケールダウンのたびに接続を落とさないよう最大ACUを基準に算出する。API一般メタデータはdynamicでもv2で最大ACU変更後の反映には再起動が必要。','最大32 ACU時の公式参考値は3000だが実機確認が必要。3000接続を同時に動かすCPU能力の保証ではない。アプリ同時実行は別に小さく制限する。','S17'),
('sql_mode','厳格モードを明示','今回のAWS API返値は0であり、Communityの既定文字列をAuroraの実測値として転記しない。業務データの桁落ちや不正日付を黙認しないため明示設定する。','ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTIONを候補とし、既存SQLと取込ファイルを回帰試験する。','S53 S56'),
('分離レベル','REPEATABLE-READを基準に継続','ロック待ちだけを理由にREAD-COMMITTEDへ全面変更すると、同じ処理の読み直し結果が変わる。Reader向けのaurora_read_replica_read_committedはさらに別の最適化である。','オンラインは既存整合性を守る。バッチRCは業務上の読み取り一貫性を確認した専用処理に限定。共用Proxyの基準値はRRのまま。','S53 S20'),
('耐久性','コミットの安全性を弱めない','innodb_flush_log_at_trx_commit=1、innodb_trx_commit_allow_data_loss=0。Auroraは独自ストレージで耐久性を実装するため、通常MySQLのディスク最適化を機械的に流用しない。','sync_binlogはbinlog利用時の話。Globalのストレージ複製を高速化するためbinlogをONにする、という説明は誤り。','S20 S15'),
('同居のロック上限','共通5秒、バッチは分割・再実行','オンライン5秒、バッチ専用DBなら30秒という比較は可能。しかし共有Writerに同居する基準設計は5秒に揃え、バッチが長いロックを抱えないようにする。','innodb_rollback_on_timeout=ONを候補にし、アプリもトランザクション全体をrollback。デッドロック再試行は冪等なチャンク単位で行う。','S54 設計提案'),
('SESSION変更とProxy','必要性とピン留めを両方評価','SET SESSION innodb_lock_wait_timeout等を接続ごとに変えるとピン留めを招く場合がある。安全を捨てるフィルターで回避することは推奨しない。','オンラインのSELECT時間制限はMAX_EXECUTION_TIMEヒント、JDBC期限、業務期限を組み合わせる。必要なら別Proxyと接続予算を持つ。','S09 S53'),
('変更の配布','両地域を同じIaCから生成','Global複製はパラメータ群、SG、Secrets、SSMをすべて同一に維持する機能ではない。大阪だけ古い設定のままだと昇格後に別の動作になる。','同じ意味のパラメータ値を地域別に管理。差分検査で業務値の一致と、地域ARN等の意図的差分を区別。static、v2例外、Proxy再起動要件を個別確認する。','S08 S21'),
])
